import{_ as i,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Crimson/Seastore Meeting 2022-10-19","description":"","frontmatter":{"title":"Ceph Crimson/Seastore Meeting 2022-10-19","date":"2022-10-19T00:00:00.000Z","updated":"2022-10-21T00:00:00.000Z","tags":["Ceph","Crimson Suite","distributed storage","scrub","performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-10-19.md","filePath":"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-10-19.md","lastUpdated":1780460162000}'),t={name:"posts/2022/Ceph_Crimson_Seastore_Meeting_2022-10-19.md"};function a(s,e,n,p,u,d){return l(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>本次会议主要讨论了Ceph Crimson Suite的开发进度和相关议题。以下是会议的主要内容：</p><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>Crimson Suite 重组</strong></p><ul><li>已合并一个PR，将c-store相关内容移至Crimson rados experimental Suite。</li><li>RBD测试尚未通过，主要涉及额外快照支持问题，Erratic正在处理。</li></ul></li><li><p><strong>安全特性增强</strong></p><ul><li>提交了一个PR，增加了Crimson和非Corpson用户的安全特性。</li><li>添加了OSD map标志和pool标志，以防止Crimson osds在未设置标志的情况下创建pgs。</li><li>研究添加配置选项，以便在不传递命令行参数的情况下更改<code>--s p</code>选项。</li></ul></li><li><p><strong>Scrub工作进展</strong></p><ul><li>计划继续推进scrub工作。</li></ul></li><li><p><strong>Messenger V2协议实现</strong></p><ul><li>King John正在审查随机块管理器和Messenger V2协议实现。</li><li>需要将协议握手阶段和协议就绪阶段分离，以支持mod core。</li></ul></li><li><p><strong>Crimson Loop优化</strong></p><ul><li>Junior发现Crimson Loop可能导致栈溢出，正在研究Sister Loop的实现并尝试应用到Crimson。</li></ul></li><li><p><strong>Open SSO和Segmentation问题</strong></p><ul><li>Jensen发现重复的 Humanity问题，怀疑是配置差异导致，询问是否有关于Open SSO或Segmentation的更新。</li></ul></li><li><p><strong>内存管理问题</strong></p><ul><li>讨论了关于内存存储的PR，涉及使用分区或多设备的问题，存在一些bug需要调试。</li></ul></li><li><p><strong>LBA树指针问题</strong></p><ul><li>完成了LBA树指针的调试，正在尝试添加LBA叶子节点和逻辑扩展之间的指针。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确保 Crimson rados 测试套件稳定。</li><li>完成快照实现，确保 ADM 安装和文档完善。</li><li>推进 scrub 工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化和稳定 Crimson rados 测试套件。</li><li>完成快照实现，确保 Crimson 的功能稳定。</li><li>推进 scrub 工作，确保 Reef 代码冻结前的准备工作。</li><li>在明年一月，重点将转向性能优化和 c-store 相关工作。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>会议中还讨论了关于 Open SSO 和 Segmentation 的问题，以及内存管理和 LBA 树指针的优化工作。</li><li>强调了确保 Crimson 功能稳定的重要性，以便进行性能测试。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议结束时，鼓励团队成员继续关注并贡献于上述目标，确保 Crimson 在 Reef 代码冻结前达到稳定状态。</li><li>会议最后提醒大家有一个愉快的一周，并结束了会议。</li></ul>',12)])])}const c=i(t,[["render",a]]);export{h as __pageData,c as default};
